    image_patch = ImagePatch(image)
    pizza_patches = image_patch.find("slice of pizza")
    plate_patches = image_patch.find("paper plate")

    if not pizza_patches:
        return image_patch
    if not plate_patches:
        return pizza_patches[0]

    closest_to_camera = pizza_patches[0]
    closest_distance = float('inf')

    for pizza in pizza_patches:
        for plate in plate_patches:
            distance_to_camera = pizza.compute_depth() + plate.compute_depth()
            if distance_to_camera < closest_distance:
                closest_distance = distance_to_camera
                closest_to_camera = pizza

    return closest_to_camera

modern_c4_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    pizza_patches = image_patch.find("pizza slice")
    plate_patches = image_patch.find("paper plate")

    if not pizza_patches or not plate_patches:
        return image_patch

    pizza_depths = [(p, p.compute_depth()) for p in pizza_patches]
    plate_depths = [(p, p.compute_depth()) for p in plate_patches]

    pizza_closest_to_plate = min(pizza_depths, key=lambda x: abs(x[1] - min(plate_depths, key=lambda y: y[1])[1]))

    return min(pizza_closest_to_plate[0], key=lambda p: p.compute_depth())

